import type { BankQuestion } from "@/lib/bank";

/** Chemical Bonding and Molecular Structure (Chemistry (JEE/NEET)): 128 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-chemical-bonding-1","question":"The shape of the BF₃ molecule is:","options":["Trigonal pyramidal","Trigonal planar","Tetrahedral","T-shaped"],"answer":1,"explanation":"Boron in BF₃ has three bond pairs and no lone pair (sp² hybridised), so the molecule is trigonal planar with 120° bond angles.","difficulty":"easy","source":"NEET"},
  {"id":"chem-chemical-bonding-2","question":"According to molecular orbital theory, the bond order of N₂ is:","options":["1","2","3","2.5"],"answer":2,"explanation":"N₂ has 10 bonding and 4 antibonding valence electrons (14 electrons total): bond order = (10 − 4)/2 = 3, a triple bond.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-3","question":"The hybridisation of carbon in methane (CH₄) is:","options":["sp","sp²","sp³","sp³d"],"answer":2,"explanation":"Carbon forms four equivalent σ bonds pointing to the corners of a tetrahedron (109.5°), which requires sp³ hybridisation.","difficulty":"easy","source":"NEET"},
  {"id":"chem-chemical-bonding-4","question":"The shape of the NH₃ molecule according to VSEPR theory is:","options":["Trigonal planar","Trigonal pyramidal","Tetrahedral","Bent"],"answer":1,"explanation":"N has three bond pairs and one lone pair (AB₃E). The electron pairs are arranged tetrahedrally, but the molecular shape (positions of atoms only) is trigonal pyramidal with a 107° angle.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-bonding-5","question":"Which of the following molecules has zero dipole moment?","options":["H₂O","SO₂","CO₂","NH₃"],"answer":2,"explanation":"CO₂ is linear, so the two equal and opposite C=O bond dipoles cancel. H₂O and SO₂ are bent and NH₃ is pyramidal, so their bond dipoles do not cancel.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-6","question":"The bond order of the superoxide ion O₂⁻ is:","options":["1","1.5","2","2.5"],"answer":1,"explanation":"O₂ has bond order 2 (8 bonding, 4 antibonding valence electrons). The extra electron in O₂⁻ enters an antibonding π* orbital: (8 − 5)/2 = 1.5.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-7","question":"The hybridisation of sulfur in SF₆ is:","options":["sp³","sp³d","sp³d²","sp³d³"],"answer":2,"explanation":"S in SF₆ has six bond pairs and no lone pair, giving an octahedral geometry that requires sp³d² hybridisation.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-bonding-8","question":"The strongest hydrogen bond is formed in:","options":["HF","H₂O","NH₃","HCl"],"answer":0,"explanation":"Hydrogen bond strength increases with the electronegativity and small size of the atom bonded to H: F > O > N. HCl does not form effective hydrogen bonds.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-bonding-9","question":"According to Fajans' rules, which of the following chlorides has the greatest covalent character?","options":["CsCl","KCl","NaCl","LiCl"],"answer":3,"explanation":"The smallest cation (Li⁺) has the highest polarising power and distorts the Cl⁻ electron cloud the most, giving LiCl the greatest covalent character (it is soluble in organic solvents).","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-10","question":"The shape of XeF₄ is:","options":["Tetrahedral","Square planar","See-saw","Octahedral"],"answer":1,"explanation":"Xe has 8 valence electrons: four bond pairs and two lone pairs (sp³d²). The lone pairs occupy opposite axial positions of the octahedron, leaving a square planar molecule.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-11","question":"Which of the following species is paramagnetic?","options":["N₂","O₂²⁻","CO","N₂⁺"],"answer":3,"explanation":"N₂ and CO (14 electrons) and O₂²⁻ (18 electrons) have all electrons paired. N₂⁺ has 13 electrons, leaving one unpaired electron in the σ2p_z orbital, so it is paramagnetic.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-12","question":"The correct order of bond angles is:","options":["CH₄ > NH₃ > H₂O > H₂S","NH₃ > CH₄ > H₂O > H₂S","CH₄ > H₂O > NH₃ > H₂S","H₂S > H₂O > NH₃ > CH₄"],"answer":0,"explanation":"CH₄ 109.5° > NH₃ 107° > H₂O 104.5° > H₂S 92°. Lone pairs compress the angle, and in H₂S the low electronegativity of S and its larger size make the angle close to 90°.","difficulty":"hard","source":"NEET"},
  {"id":"chem-chemical-bonding-13","question":"The dipole moment of NH₃ (1.47 D) is much larger than that of NF₃ (0.23 D). This is because:","options":["F is more electronegative than H, so NF₃ bonds are less polar","In NH₃ the lone-pair moment adds to the N–H bond moments, while in NF₃ it opposes the N–F bond moments","NF₃ is planar and NH₃ is pyramidal","NH₃ forms hydrogen bonds"],"answer":1,"explanation":"Both molecules are pyramidal. In NH₃ the N–H dipoles point towards N, the same direction as the lone pair, so they add. In NF₃ the N–F dipoles point away from N, opposing the lone-pair moment, so they largely cancel.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-14","question":"The number of σ and π bonds in CH₂=CH–C≡N is:","options":["6 σ and 3 π","5 σ and 3 π","6 σ and 2 π","7 σ and 3 π"],"answer":0,"explanation":"σ bonds: three C–H, one C=C (its σ), one C–C and one C≡N (its σ) = 6. π bonds: one in C=C and two in C≡N = 3.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-15","question":"The correct order of O–O bond length is:","options":["O₂⁺ < O₂ < O₂⁻ < O₂²⁻","O₂²⁻ < O₂⁻ < O₂ < O₂⁺","O₂ < O₂⁺ < O₂⁻ < O₂²⁻","O₂⁻ < O₂ < O₂⁺ < O₂²⁻"],"answer":0,"explanation":"Bond orders: O₂⁺ 2.5, O₂ 2, O₂⁻ 1.5, O₂²⁻ 1. Higher bond order means shorter bond, so bond length increases in the order O₂⁺ < O₂ < O₂⁻ < O₂²⁻.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-16","question":"The hybridisation of the central iodine atom in I₃⁻ and the shape of the ion are:","options":["sp³, bent","sp³d, linear","sp³d², square planar","sp², trigonal planar"],"answer":1,"explanation":"The central I has two bond pairs and three lone pairs (5 electron pairs, sp³d). The three lone pairs occupy the equatorial positions of the trigonal bipyramid, so the ion is linear.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-17","question":"The formal charge on the central oxygen atom in ozone (O₃) is:","options":["0","+1","−1","+2"],"answer":1,"explanation":"The central O has one lone pair, one double bond and one single bond: formal charge = 6 − 2 − (6/2) = +1. The singly bonded terminal O carries −1 and the doubly bonded terminal O is 0.","difficulty":"hard","source":"NEET"},
  {"id":"chem-chemical-bonding-18","question":"Which of the following species has a bond order of zero and therefore does not exist?","options":["He₂⁺","Be₂","Li₂","B₂"],"answer":1,"explanation":"Be₂ (8 electrons): σ1s² σ*1s² σ2s² σ*2s², bond order (4 − 4)/2 = 0. He₂⁺ has bond order 0.5, Li₂ has 1 and B₂ has 1.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-19","question":"How many of the following statements are correct according to molecular orbital theory? (A) O₂²⁻ is diamagnetic. (B) In N₂ the σ2p_z orbital lies lower in energy than the π2p_x and π2p_y orbitals. (C) The bond order of CO is 3. (D) In C₂ both bonds are π bonds.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A) true: all electrons in O₂²⁻ are paired. (B) false: for molecules up to N₂ (14 electrons) the π2p orbitals lie below σ2p_z; the reverse holds for O₂ and F₂. (C) true: (10 − 4)/2 = 3. (D) true: C₂ has π2p_x² π2p_y² and no σ2p electrons. Three are correct.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-20","question":"Assertion (A): p-nitrophenol has a higher boiling point than o-nitrophenol. Reason (R): o-nitrophenol has intramolecular hydrogen bonding, whereas p-nitrophenol has intermolecular hydrogen bonding.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In o-nitrophenol the –OH hydrogen bonds to the adjacent –NO₂ within the same molecule (chelation), so molecules do not associate and it is volatile (steam distillable). In the para isomer intermolecular hydrogen bonds link molecules, raising the boiling point.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-21","question":"Match the molecule (Column I) with its shape (Column II). (a) SF₄, (b) ClF₃, (c) BrF₅, (d) XeF₂. (1) Linear; (2) Square pyramidal; (3) See-saw; (4) T-shaped.","options":["a-3, b-4, c-2, d-1","a-4, b-3, c-2, d-1","a-3, b-2, c-4, d-1","a-2, b-4, c-3, d-1"],"answer":0,"explanation":"SF₄ (4 bp, 1 lp) is see-saw; ClF₃ (3 bp, 2 lp) is T-shaped; BrF₅ (5 bp, 1 lp) is square pyramidal; XeF₂ (2 bp, 3 lp) is linear.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-22","question":"A diatomic molecule AB has bond length 1.0 Å and an observed dipole moment of 1.2 D. Taking the dipole moment for complete charge separation of one electronic charge over 1 Å as 4.8 D, the percentage ionic character of the A–B bond is:","options":["12%","25%","48%","75%"],"answer":1,"explanation":"μ(100% ionic) = e × d = 4.8 D × 1.0 = 4.8 D. Percentage ionic character = (observed/ionic) × 100 = (1.2/4.8) × 100 = 25%.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-23","question":"Among PCl₅, SF₄, ClF₃, XeF₂, XeF₄ and BrF₅, the number of species in which the central atom is sp³d hybridised is:","options":["2","3","4","5"],"answer":2,"explanation":"Five electron pairs (sp³d): PCl₅ (5 bp), SF₄ (4 bp + 1 lp), ClF₃ (3 bp + 2 lp) and XeF₂ (2 bp + 3 lp) — four species. XeF₄ (4 bp + 2 lp) and BrF₅ (5 bp + 1 lp) have six pairs and are sp³d².","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-24","question":"Which statement about the NO molecule and its ions is INCORRECT?","options":["The bond order of NO is 2.5","NO is paramagnetic","NO⁺ has a shorter bond than NO","NO⁻ has a higher bond order than NO"],"answer":3,"explanation":"NO has 15 electrons: bond order (10 − 5)/2 = 2.5 with one unpaired π* electron, so it is paramagnetic. Removing that electron gives NO⁺ (bond order 3, shorter bond). Adding an electron gives NO⁻ with bond order 2, lower than NO.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-25","question":"Which of the following orders of covalent character is correct?","options":["LiI > LiBr > LiCl > LiF","LiF > LiCl > LiBr > LiI","CaCl₂ > MgCl₂ > BeCl₂","NaCl > MgCl₂ > AlCl₃"],"answer":0,"explanation":"By Fajans' rules a larger, more polarisable anion increases covalent character, so LiI > LiBr > LiCl > LiF. A smaller or more highly charged cation also increases covalent character, so BeCl₂ > MgCl₂ > CaCl₂ and AlCl₃ > MgCl₂ > NaCl; the last two options state the reverse.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-26","question":"Which of the following species has the shortest carbon–oxygen bond?","options":["CO₂","CO₃²⁻","CO","CH₃OH"],"answer":2,"explanation":"C–O bond orders: CO 3 (triple bond, 1.13 Å), CO₂ 2 (1.16 Å), CO₃²⁻ 1.33 (resonance, 1.28 Å), CH₃OH 1 (1.43 Å). Higher bond order gives the shortest bond, so CO.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-27","question":"In XeOF₄, the hybridisation of xenon, the number of lone pairs on xenon and the shape of the molecule are respectively:","options":["sp³d, 1, see-saw","sp³d², 1, square pyramidal","sp³d², 2, square planar","sp³d³, 1, pentagonal bipyramidal"],"answer":1,"explanation":"Xe has 8 valence electrons: 4 for the Xe–F bonds, 2 for the Xe=O bond and 2 left as one lone pair. Six electron domains give sp³d²; with one lone pair the shape is square pyramidal.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-28","question":"Which of the following molecules has the maximum number of lone pairs on the central atom?","options":["XeF₄","XeF₆","XeO₃","XeF₂"],"answer":3,"explanation":"Lone pairs on Xe: XeF₂ has 3 (8 − 2 bonds), XeF₄ has 2, XeF₆ has 1 and XeO₃ has 1 (the three Xe=O double bonds use 6 electrons). XeF₂ has the most.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-29","question":"Which of the following orders of boiling point is correct?","options":["H₂O > H₂Te > H₂Se > H₂S","NH₃ > PH₃ > AsH₃ > SbH₃","HF > HCl > HBr > HI","H₂S > H₂Se > H₂Te > H₂O"],"answer":0,"explanation":"H₂O (100 °C) is far above the rest because of hydrogen bonding; among the others boiling point rises with molar mass (van der Waals forces): H₂Te (−2 °C) > H₂Se (−41 °C) > H₂S (−60 °C). For HX the order is HF > HI > HBr > HCl, and SbH₃ boils above PH₃.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-30","question":"Which of the following molecules has an sp² hybridised central atom AND a non-zero dipole moment?","options":["BF₃","SO₃","SO₂","CO₂"],"answer":2,"explanation":"BF₃ and SO₃ are sp² but symmetrical trigonal planar, so their dipole moments cancel; CO₂ is sp and linear. SO₂ is sp² with one lone pair, giving a bent shape and a net dipole (1.6 D).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-31","question":"The shape of the H₂O molecule is:","options":["Tetrahedral","Bent (angular)","Trigonal planar","Linear"],"answer":1,"explanation":"O is sp³ hybridised with two lone pairs, so the molecule is bent (104.5°).","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-32","question":"The hybridisation of carbon in CO₂ is:","options":["sp","sp³","dsp²","sp²"],"answer":0,"explanation":"C forms two σ bonds and two π bonds with no lone pairs; two hybrid orbitals → sp, linear.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-33","question":"The bond order of He₂⁺ is:","options":["1","1.5","0","0.5"],"answer":3,"explanation":"He₂⁺ has 3 electrons: σ1s² σ*1s¹. Bond order = (2 − 1)/2 = 0.5, so it can exist (unlike He₂).","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-34","question":"Which of the following contains ionic, covalent and coordinate bonds?","options":["CCl₄","H₂O","NaCl","NH₄Cl"],"answer":3,"explanation":"NH₄⁺ has three N–H covalent bonds and one N→H coordinate bond, and is held to Cl⁻ by an ionic bond.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-chemical-bonding-35","question":"The shape of the chlorate ion, ClO₃⁻, is:","options":["Trigonal pyramidal","Trigonal planar","Tetrahedral","T-shaped"],"answer":0,"explanation":"Cl has 3 bond pairs and 1 lone pair (sp³), so the ion is pyramidal like NH₃. Nitrate (no lone pair) is trigonal planar.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-36","question":"Which of the following has the highest dipole moment?","options":["CH₃Cl","CHCl₃","CH₂Cl₂","CCl₄"],"answer":0,"explanation":"CH₃Cl (≈1.87 D) > CH₂Cl₂ (≈1.6 D) > CHCl₃ (≈1.0 D) > CCl₄ (0). In the more chlorinated molecules the C–Cl dipoles partly cancel.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-chemical-bonding-37","question":"Which of the following has the highest lattice enthalpy?","options":["MgO","NaCl","CaO","KCl"],"answer":0,"explanation":"Lattice enthalpy rises with ionic charges and falls with size: MgO has 2+/2− charges and the smallest cation.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-38","question":"The shape of the ICl₄⁻ ion is:","options":["Square pyramidal","Square planar","Tetrahedral","See-saw"],"answer":1,"explanation":"I has 4 bond pairs and 2 lone pairs (sp³d²); the lone pairs sit trans to each other, giving a square planar ion.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-39","question":"How many of the following statements are correct? (A) In PCl₅ the axial P–Cl bonds are longer than the equatorial ones. (B) All six S–F bonds in SF₆ are equivalent. (C) NO₂⁻ is linear. (D) BF₃ and NF₃ are both planar.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A and B are correct. C is wrong: NO₂⁻ has a lone pair on N and is bent (≈115°); NO₂⁺ is linear. D is wrong: NF₃ is pyramidal because of the lone pair on N.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-40","question":"Which pair of species has the same bond order and both members paramagnetic?","options":["N₂ and CO","C₂ and O₂","O₂²⁻ and F₂","O₂⁺ and NO"],"answer":3,"explanation":"O₂⁺ (15 e⁻) and NO (15 e⁻) both have bond order 2.5 and one unpaired electron. N₂/CO and O₂²⁻/F₂ match bond orders but are diamagnetic; C₂ is diamagnetic.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-41","question":"In the solid state PCl₅ exists as [PCl₄]⁺[PCl₆]⁻. The hybridisations of phosphorus in the cation and the anion are respectively:","options":["sp³d and sp³d²","sp³d² and sp³","sp³ and sp³d","sp³ and sp³d²"],"answer":3,"explanation":"[PCl₄]⁺ is tetrahedral (sp³) and [PCl₆]⁻ is octahedral (sp³d²); gaseous PCl₅ is sp³d.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-chemical-bonding-42","question":"The correct order of bond angle is:","options":["PH₃ > NH₃ > NF₃","NH₃ > PH₃ > NF₃","NF₃ > NH₃ > PH₃","NH₃ > NF₃ > PH₃"],"answer":3,"explanation":"NH₃ ≈ 107°; NF₃ ≈ 102° (bond pairs drawn to F, less repulsion); PH₃ ≈ 93.5° (larger P, nearly pure p bonding).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-43","question":"Assertion (A): The bond angle in H₂O (104.5°) is larger than that in H₂S (about 92°). Reason (R): The more electronegative oxygen pulls the bond pairs closer to itself, increasing bond pair–bond pair repulsion.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Both true and R explains A: in H₂S the bond pairs lie farther from the larger, less electronegative S and repel less, so S uses almost pure p orbitals.","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-chemical-bonding-44","question":"How many of the following are tetrahedral with an sp³ central atom: NH₄⁺, BF₄⁻, SF₄, XeF₄, SO₄²⁻, ClO₄⁻, PCl₄⁺?","options":["6","3","4","5"],"answer":3,"explanation":"NH₄⁺, BF₄⁻, SO₄²⁻, ClO₄⁻ and PCl₄⁺ are tetrahedral. SF₄ is see-saw (sp³d) and XeF₄ square planar (sp³d²).","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-45","question":"The correct order of Lewis acid strength of the boron trihalides is:","options":["BF₃ > BCl₃ > BBr₃","BBr₃ > BCl₃ > BF₃","BCl₃ > BF₃ > BBr₃","All are equal"],"answer":1,"explanation":"pπ–pπ back-donation from the halogen into the empty 2p orbital of B is strongest for F (similar orbital size), which reduces the electron deficiency of BF₃ the most. Electronegativity alone would predict the reverse.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-chemical-bonding-46", "question": "In which of the following molecules does the central atom have an incomplete octet?", "options": ["NH₃", "CH₄", "BF₃", "H₂O"], "answer": 2, "explanation": "Boron in BF₃ has only three bond pairs, i.e. six electrons around it, so its octet is incomplete. N, C and O in the other molecules all have eight electrons.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-chemical-bonding-47", "question": "A covalent bond formed by the sideways (lateral) overlap of two parallel p orbitals is a:", "options": ["σ bond", "π bond", "Hydrogen bond", "Ionic bond"], "answer": 1, "explanation": "Sideways overlap of p orbitals gives a π bond, with electron density above and below the internuclear axis. Head-on (axial) overlap gives a σ bond.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-chemical-bonding-48", "question": "In the carbonate ion, CO₃²⁻, the C–O bond order is:", "options": ["4/3", "1", "3/2", "2"], "answer": 0, "explanation": "CO₃²⁻ has three equivalent resonance structures with one C=O and two C–O⁻ bonds; total bonds = 4 spread over 3 positions, so bond order = 4/3. 3/2 is the bond order in NO₂⁻ or the carboxylate ion.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-49", "question": "Which of the following diatomic molecules has the highest bond dissociation enthalpy?", "options": ["O₂", "F₂", "N₂", "Cl₂"], "answer": 2, "explanation": "N₂ has a triple bond (bond order 3) and a bond enthalpy of about 946 kJ/mol, far above O₂ (bond order 2, about 498), Cl₂ (242) and F₂ (158).", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-50", "question": "Which set of conditions most favours the formation of an ionic bond between a metal M and a non-metal X?", "options": ["High ionisation enthalpy of M and low lattice enthalpy", "Low ionisation enthalpy of M and positive electron gain enthalpy of X", "Small, highly charged cation and large anion", "Low ionisation enthalpy of M, highly negative electron gain enthalpy of X and high lattice enthalpy"], "answer": 3, "explanation": "Easy loss of an electron by M, ready gain by X and a large release of lattice energy all favour ionic bonding. A small, highly charged cation with a large anion favours covalent character (Fajans' rules).", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-chemical-bonding-51", "question": "The hybridisation of boron in BF₃ and in BF₄⁻ is respectively:", "options": ["sp³ and sp²", "sp² and sp³", "sp² and sp²", "sp and sp³"], "answer": 1, "explanation": "BF₃ has three bond pairs and no lone pair (sp², trigonal planar). In BF₄⁻ the fourth F⁻ donates a pair into boron's empty p orbital, giving four bond pairs (sp³, tetrahedral).", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-52", "question": "The H–N–H bond angle in NH₃ (107°) is larger than the H–O–H bond angle in H₂O (104.5°) because:", "options": ["H₂O has two lone pairs, and lone pair–lone pair repulsion compresses the bond angle more", "Nitrogen is more electronegative than oxygen", "NH₃ is sp² hybridised while H₂O is sp³", "Hydrogen bonding is stronger in NH₃"], "answer": 0, "explanation": "Both central atoms are sp³. O has two lone pairs and N only one; lone pair–lone pair repulsion > lone pair–bond pair > bond pair–bond pair, so the angle in H₂O shrinks more. Oxygen, not nitrogen, is the more electronegative.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-53", "question": "Which of the following molecules is NOT planar?", "options": ["BF₃", "C₂H₄", "XeF₄", "CH₂=C=CH₂"], "answer": 3, "explanation": "In allene the central carbon is sp hybridised and its two π bonds are perpendicular, so the two CH₂ groups lie in perpendicular planes. BF₃ (trigonal planar), ethene and square planar XeF₄ are all planar.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-54", "question": "Which of the following species does NOT have a bond order of 3?", "options": ["CO", "NO", "CN⁻", "NO⁺"], "answer": 1, "explanation": "CO, CN⁻ and NO⁺ each have 14 electrons (isoelectronic with N₂) and bond order 3. NO has 15 electrons; the extra one goes into a π* orbital, giving bond order 2.5.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-55", "question": "Water (boiling point 373 K) boils at a much higher temperature than HF (293 K), even though fluorine is more electronegative than oxygen. This is because:", "options": ["The H–F bond is weaker than the O–H bond", "HF is non-polar", "Each water molecule can form on average two hydrogen bonds (two H atoms and two lone pairs), while HF has only one H to donate", "HF molecules have a larger molar mass"], "answer": 2, "explanation": "A single F–H···F hydrogen bond is stronger than O–H···O, but HF has only one H per molecule, so on average it forms only one hydrogen bond per molecule; water forms two, giving a 3-D network that needs more energy to break.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-56", "question": "The shape of thionyl chloride, SOCl₂, and the hybridisation of sulphur in it are:", "options": ["Trigonal planar, sp²", "Trigonal pyramidal, sp³", "Tetrahedral, sp³", "T-shaped, sp³d"], "answer": 1, "explanation": "S (6 valence electrons) forms one S=O and two S–Cl bonds and keeps one lone pair: three σ bonds + one lone pair = steric number 4, sp³, so the shape is trigonal pyramidal. The π bond does not count towards hybridisation.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-57", "question": "In the octahedral SF₆ molecule, the number of F–S–F bond angles equal to 90° is:", "options": ["6", "8", "12", "24"], "answer": 2, "explanation": "Each F has four neighbours at 90° and one opposite it at 180°. Counting each pair once: 6 × 4/2 = 12 angles of 90° (and 3 of 180°).", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-chemical-bonding-58", "question": "Trisilylamine, N(SiH₃)₃, is planar and a much weaker base than trimethylamine, N(CH₃)₃, which is pyramidal. The usual explanation is that:", "options": ["The lone pair on N is delocalised into vacant orbitals of silicon (pπ–dπ back bonding), making N effectively sp²", "Silicon is more electronegative than carbon", "Si–N bonds are ionic", "SiH₃ groups are smaller than CH₃ groups"], "answer": 0, "explanation": "Delocalisation of nitrogen's lone pair towards silicon (classically described as pπ–dπ bonding) flattens N to a trigonal planar geometry and makes the lone pair less available, so the base is weaker. Carbon has no such low-lying vacant orbitals. Silicon is less electronegative than carbon.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-chemical-bonding-59", "question": "The dipole moment of H₂O is 1.85 D and its H–O–H bond angle is 104.5°. The O–H bond moment is about (cos 52.25° = 0.612):", "options": ["0.93 D", "1.85 D", "3.02 D", "1.51 D"], "answer": 3, "explanation": "The two bond moments add as vectors: μ = 2μ(O–H) cos(104.5°/2). So μ(O–H) = 1.85/(2 × 0.612) = 1.85/1.224 = 1.51 D. 0.93 D simply halves 1.85 D and ignores the angle.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-chemical-bonding-60", "question": "How many of the following statements are correct according to molecular orbital theory? (A) B₂ is paramagnetic. (B) C₂ is diamagnetic, and both of its bonds are π bonds. (C) The bond order of B₂ is 1. (D) Li₂ is paramagnetic.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "With s–p mixing, B₂ is …π2p¹ π2p¹ (two unpaired electrons, bond order (6 − 4)/2 = 1) and C₂ is …π2p⁴ (all paired, bond order 2 from two π bonds). Li₂ is σ2s² with all electrons paired, so (D) is false. Three are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-61", "question": "Assertion (A): CO₂ is a gas at room temperature, whereas SiO₂ is a high-melting solid. Reason (R): Carbon forms strong pπ–pπ double bonds with oxygen, giving discrete O=C=O molecules, whereas silicon forms single Si–O bonds that link into a three-dimensional network.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Small carbon overlaps well with oxygen's p orbitals to make double bonds, so CO₂ molecules are held only by weak van der Waals forces. Larger Si makes poor π bonds and instead forms four Si–O single bonds per atom, giving a giant covalent solid.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-62", "question": "Match the species (Column I) with the number of lone pairs on its central atom (Column II). (a) XeO₃, (b) IF₇, (c) ClF₃, (d) I₃⁻. (1) 0; (2) 1; (3) 2; (4) 3.", "options": ["a-1, b-2, c-3, d-4", "a-2, b-1, c-3, d-4", "a-2, b-1, c-4, d-3", "a-3, b-1, c-2, d-4"], "answer": 1, "explanation": "XeO₃: Xe uses 6 of its 8 electrons in three Xe=O bonds, leaving 1 lone pair (pyramidal). IF₇: 7 bonds, 0 lone pairs. ClF₃: 3 bonds + 2 lone pairs (T-shaped). I₃⁻: central I has 3 lone pairs (linear). So a-2, b-1, c-3, d-4.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-63", "question": "By molecular orbital theory, the number of electrons in antibonding orbitals (counting σ*1s as well) in O₂²⁻ minus the number in N₂ is:", "options": ["0", "2", "4", "6"], "answer": 2, "explanation": "O₂²⁻ (18 electrons): σ*1s², σ*2s², π*2p⁴, i.e. 8 antibonding electrons. N₂ (14 electrons): σ*1s², σ*2s², i.e. 4 antibonding electrons. Difference = 8 − 4 = 4.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-chemical-bonding-64", "question": "Which of the following pairs is NOT isostructural?", "options": ["XeF₄ and ICl₄⁻", "SiCl₄ and PCl₄⁺", "NO₃⁻ and CO₃²⁻", "SO₃²⁻ and SO₃"], "answer": 3, "explanation": "SO₃²⁻ has a lone pair on S (three bond pairs + one lone pair) and is trigonal pyramidal, while SO₃ has no lone pair and is trigonal planar. The other pairs share shapes: square planar, tetrahedral and trigonal planar.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-65", "question": "How many of the following statements are correct? (A) Intramolecular hydrogen bonding raises the boiling point of a compound. (B) Hydrogen fluoride exists as zig-zag (HF)ₙ chains in the solid and liquid. (C) Ethanol mixes with water mainly because it forms hydrogen bonds with water. (D) Hydrogen bonds are stronger than covalent bonds.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(B) and (C) are correct. (A) is false: intramolecular hydrogen bonding stops molecules from associating and lowers the boiling point (o-nitrophenol is steam volatile). (D) is false: hydrogen bonds (about 10–40 kJ/mol) are much weaker than covalent bonds. Two are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-66", "question": "In one Lewis structure of the nitrate ion, NO₃⁻, the formal charges on N, on the double-bonded O and on each single-bonded O are respectively:", "options": ["+1, 0, −1", "0, 0, −1", "+1, −1, 0", "−1, 0, +1"], "answer": 0, "explanation": "Formal charge = valence electrons − lone-pair electrons − ½ bonding electrons. N: 5 − 0 − 4 = +1. Double-bonded O: 6 − 4 − 2 = 0. Single-bonded O: 6 − 6 − 1 = −1. Sum = +1 + 0 − 2 = −1, the charge on the ion.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-67", "question": "The correct order of the O–N–O bond angle in NO₂⁺, NO₂ and NO₂⁻ is:", "options": ["NO₂ > NO₂⁺ > NO₂⁻", "NO₂⁻ > NO₂ > NO₂⁺", "NO₂⁺ > NO₂⁻ > NO₂", "NO₂⁺ > NO₂ > NO₂⁻"], "answer": 3, "explanation": "NO₂⁺ has no non-bonding electrons on N and is linear (180°). NO₂ has one odd electron on N (about 134°), and NO₂⁻ has a full lone pair (about 115°). A lone pair repels more than a single electron, so the angle shrinks more.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-68", "question": "How many of the following species are paramagnetic: NO, NO₂, N₂O, ClO₂, O₃, N₂O₄?", "options": ["2", "3", "4", "5"], "answer": 1, "explanation": "Count electrons: NO 15, NO₂ 23 and ClO₂ 33 are odd-electron molecules and so paramagnetic. N₂O (22), O₃ (24) and N₂O₄ (46) have all electrons paired. Three are paramagnetic.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-69", "question": "How many of the following have zero dipole moment: CO₂, SO₂, BF₃, NF₃, CCl₄, trans-1,2-dichloroethene, p-dichlorobenzene, PCl₅?", "options": ["4", "5", "6", "7"], "answer": 2, "explanation": "Bond dipoles cancel in linear CO₂, trigonal planar BF₃, tetrahedral CCl₄, trans-ClCH=CHCl, p-C₆H₄Cl₂ and trigonal bipyramidal PCl₅: 6 molecules. SO₂ (bent) and NF₃ (pyramidal) are polar.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-chemical-bonding-70", "question": "Assertion (A): O₂ is paramagnetic. Reason (R): The O₂ molecule contains an odd number of electrons.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "A is true: O₂ has two unpaired electrons in the degenerate π*2p orbitals. R is false: O₂ has 16 electrons (an even number); its paramagnetism comes from Hund's rule in the π* level, which Lewis theory cannot explain.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id":"chem-chemical-bonding-71","question":"In the conventional (expanded-octet) description, which of the following species contains pπ–dπ bonding?","options":["SO₄²⁻","NO₃⁻","BF₃","CO₃²⁻"],"answer":0,"explanation":"In SO₄²⁻ the S=O π bonds are described as overlap of filled O 2p with vacant S 3d orbitals (pπ–dπ). C and N have no d orbitals, so CO₃²⁻ and NO₃⁻ have pπ–pπ bonds; in BF₃ the back-bonding is also pπ–pπ.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "chem-chemical-bonding-72", "question": "The number of lone pairs on xenon in XeF₆ and the shape of the molecule are:", "options": ["0, regular octahedral", "1, distorted octahedral", "2, square planar", "1, pentagonal bipyramidal"], "answer": 1, "explanation": "Xe has 8 valence electrons: 6 bond pairs and 1 lone pair = 7 electron pairs (sp³d³). The stereo-active lone pair distorts the octahedron (capped/distorted octahedral). A regular octahedron would need no lone pair.", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"chem-chemical-bonding-73","question":"In which of the following molecules are all the bonds from the central atom of equal length?","options":["SF₄","PCl₅","XeF₄","BrF₅"],"answer":2,"explanation":"XeF₄ is square planar with the two lone pairs trans to each other, so all four Xe–F bonds are equivalent. SF₄ and PCl₅ have distinct axial and equatorial bonds, and BrF₅ has an apical bond different from the four basal ones.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-74","question":"Which of the following species is isostructural with ClF₃?","options":["BF₃","NF₃","PCl₃","XeF₃⁺"],"answer":3,"explanation":"ClF₃ has 3 bond pairs and 2 lone pairs (sp³d) → T-shaped. XeF₃⁺: Xe has 8 − 1 = 7 electrons, 3 used in bonds, leaving 2 lone pairs → also T-shaped. BF₃ is trigonal planar, NF₃ and PCl₃ are pyramidal.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-bonding-75", "question": "In CH₂F₂ the H–C–H and F–C–F bond angles compare with the ideal tetrahedral angle (109.5°) as:", "options": ["H–C–H < 109.5° < F–C–F", "H–C–H > 109.5° > F–C–F", "both equal 109.5°", "both less than 109.5°"], "answer": 1, "explanation": "By Bent's rule carbon puts more p character into the bonds to the more electronegative F and more s character into the C–H bonds. More s character widens the H–C–H angle (≈ 113.7°) and more p character narrows F–C–F (≈ 108.3°).", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id": "chem-chemical-bonding-76", "question": "Which of the following is the correct order of dipole moments of the methyl halides?", "options": ["CH₃F > CH₃Cl > CH₃Br > CH₃I", "CH₃I > CH₃Br > CH₃Cl > CH₃F", "CH₃Cl > CH₃F > CH₃Br > CH₃I", "CH₃Cl > CH₃Br > CH₃F > CH₃I"], "answer": 2, "explanation": "μ = charge × distance. The C–F bond is the most polar but also much shorter, so CH₃F (1.85 D) falls just below CH₃Cl (1.87 D); then CH₃Br (1.81 D) > CH₃I (1.62 D). Following electronegativity alone gives the tempting first option.", "difficulty": "hard", "source": "JEE Advanced pattern"},
  {"id": "chem-chemical-bonding-77", "question": "Ag⁺ (115 pm) is larger than Na⁺ (102 pm), yet AgCl is much more covalent (and lower melting) than NaCl. The best explanation is that:", "options": ["Ag is more electronegative than Cl", "Ag⁺ has an 18-electron (4d¹⁰) outer shell that shields the nuclear charge poorly, so it polarises Cl⁻ more strongly", "Ag⁺ carries a higher charge than Na⁺", "AgCl has a higher lattice enthalpy than NaCl because Ag⁺ is larger"], "answer": 1, "explanation": "Fajans' rules: a cation with a pseudo-noble-gas (n − 1)d¹⁰ ns⁰ configuration polarises anions more than a noble-gas cation of similar size, because d electrons shield poorly. That outweighs the small size difference, so AgCl (m.p. 455 °C) is more covalent than NaCl (801 °C).", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-bonding-78","question":"In which option do ALL the listed molecules actually exist?","options":["PCl₅, SF₆, XeF₄","OF₄, SF₄, SeF₄","NCl₅, PCl₅, SF₆","PF₅, BiCl₅, SF₆"],"answer":0,"explanation":"NCl₅ and OF₄ cannot exist because second-period N and O have no d orbitals to expand the octet; BiCl₅ is not formed because of the inert pair effect (Bi(V) is too oxidising for Cl⁻). PCl₅, SF₆ and XeF₄ are all well known.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-bonding-79", "question": "Among HF, HCl, HBr and HI, the compound with the LOWEST boiling point is:", "options": ["HF", "HCl", "HBr", "HI"], "answer": 1, "explanation": "HF boils highest (about 20 °C) because of strong hydrogen bonding. Among the others there is no significant hydrogen bonding and van der Waals forces grow with size: HCl (−85 °C) < HBr (−67 °C) < HI (−35 °C). HI is the trap for those who think the order simply reverses.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-bonding-80","question":"The shape of XeO₂F₂ is:","options":["Square planar","See-saw","Tetrahedral","Trigonal pyramidal"],"answer":1,"explanation":"Xe (8 valence electrons) forms two Xe–F and two Xe=O bonds; counting σ pairs, that is 4 bond pairs + 1 lone pair = 5 pairs (sp³d), giving a see-saw (distorted trigonal bipyramid) with the lone pair equatorial. Square planar would need 2 lone pairs.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-bonding-81", "question": "How many of the following statements are correct according to molecular orbital theory? (A) N₂⁺ and N₂⁻ have the same bond order. (B) N₂⁺ is more stable than N₂⁻. (C) O₂²⁺ has a bond order of 3. (D) In C₂ both bonds of the double bond are π bonds.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "N₂⁺ (13 e⁻) and N₂⁻ (15 e⁻) both have bond order 2.5 ✓, but N₂⁻ has an electron in an antibonding π* orbital, so N₂⁺ is more stable ✓. O₂²⁺ (14 e⁻) has bond order 3 ✓. C₂ has bond order 2 from two filled π2p orbitals with no σ2p electrons ✓. All four.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-bonding-82","question":"How many of the following species are square planar: XeF₄, SF₄, ICl₄⁻, BrF₄⁻, XeO₂F₂, XeOF₄, SiF₄?","options":["2","4","3","5"],"answer":2,"explanation":"Square planar needs 4 bond pairs + 2 lone pairs (sp³d²): XeF₄, ICl₄⁻ and BrF₄⁻ = 3. SF₄ and XeO₂F₂ (4 bp + 1 lp) are see-saw, XeOF₄ (5 bp + 1 lp) is square pyramidal and SiF₄ is tetrahedral.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-bonding-83", "question": "Assuming the C–Cl bond moments simply add vectorially (benzene ring regular hexagon), the ratio of the dipole moment of o-dichlorobenzene to that of m-dichlorobenzene is:", "options": ["2", "1/√3", "√2", "√3"], "answer": 3, "explanation": "The C–Cl bonds are at 60° in the ortho and 120° in the meta isomer. Resultant = 2μ cos(θ/2): ortho 2μ cos 30° = √3 μ, meta 2μ cos 60° = μ. Ratio = √3 (para is zero). Using the 60°/120° angles directly in cos θ (instead of θ/2) gives wrong ratios.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-84","question":"The total number of lone pairs of electrons on all the atoms of XeOF₄ is:","options":["15","13","14","16"],"answer":0,"explanation":"Xe (8 e⁻) forms 4 Xe–F bonds and one Xe=O bond, using 6 electrons and leaving 1 lone pair. Each F carries 3 lone pairs (12) and the doubly bonded O carries 2. Total = 1 + 12 + 2 = 15; counting only the central atom's lone pair gives 1, a different question.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "chem-chemical-bonding-85", "question": "How many of the following species are paramagnetic: O₂⁻, NO⁻, CN⁻, B₂, C₂²⁻, NO⁺, O₂²⁻, CN?", "options": ["3", "4", "5", "2"], "answer": 1, "explanation": "O₂⁻ (17 e⁻, one unpaired), NO⁻ (16 e⁻, isoelectronic with O₂: two unpaired π*), B₂ (two unpaired π) and the CN radical (13 e⁻) are paramagnetic: 4. CN⁻, C₂²⁻ and NO⁺ (14 e⁻, like N₂) and O₂²⁻ (18 e⁻) are diamagnetic.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-86","question":"In allene, H₂C=C=CH₂, the hybridisations of the three carbon atoms (in order) and the angle between the plane of one terminal CH₂ group and that of the other are:","options":["sp², sp², sp²; 90°","sp², sp, sp²; 0° (molecule planar)","sp², sp, sp²; 90°","sp, sp², sp; 180°"],"answer":2,"explanation":"The central carbon is sp and uses two perpendicular p orbitals for its two π bonds. Each π bond fixes the plane of the CH₂ group at its end, so the two terminal H–C–H planes are perpendicular (90°) and allene is not planar.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-87","question":"Which of the following is the correct order of bond angle?","options":["ClO₂ < Cl₂O < OF₂","Cl₂O < OF₂ < ClO₂","OF₂ < ClO₂ < Cl₂O","OF₂ < Cl₂O < ClO₂"],"answer":3,"explanation":"OF₂ ≈ 103°: very electronegative F pulls bond pairs away from O, letting the lone pairs close the angle. Cl₂O ≈ 111°: bonding pairs nearer O plus steric repulsion of the large Cl atoms open it. ClO₂ ≈ 118°: Cl is central and the partial Cl=O double-bond character (greater bond-pair repulsion) opens the angle further. Hence OF₂ < Cl₂O < ClO₂.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-chemical-bonding-88", "question": "Assertion (A): The B–F bond in BF₃ (about 130 pm) is shorter than the B–F bond in BF₄⁻ (about 143 pm). Reason (R): In BF₃, filled 2p orbitals of fluorine donate into the vacant 2p orbital of sp² boron, giving partial double-bond character that is lost when boron becomes sp³ in BF₄⁻.", "options": ["Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true", "Both A and R are true and R is the correct explanation of A"], "answer": 3, "explanation": "pπ–pπ back-bonding is possible only while boron has an empty p orbital (planar sp² BF₃). In tetrahedral BF₄⁻ that orbital is used for the fourth σ bond, so the bonds are pure single bonds and longer. R explains A.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "chem-chemical-bonding-89", "question": "How many of the following are correctly explained by hydrogen bonding? (A) Ice is less dense than liquid water. (B) KHF₂ exists, but KHCl₂ does not. (C) o-Nitrophenol is steam-volatile because of intermolecular hydrogen bonding. (D) Ethanol boils much higher than its isomer dimethyl ether.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A ✓ (open, cage-like H-bonded lattice of ice); B ✓ (the very strong F–H···F bond gives HF₂⁻); D ✓ (O–H···O in ethanol, absent in ether). C is wrong: o-nitrophenol is steam-volatile because its hydrogen bond is intramolecular, which stops molecules associating. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-chemical-bonding-90","question":"Which of the following trigonal bipyramidal phosphorus halides has zero dipole moment?","options":["PCl₃F₂","PCl₂F₃","PCl₄F","PClF₄"],"answer":0,"explanation":"In a trigonal bipyramid the more electronegative atoms occupy the axial positions (Bent's rule). In PCl₃F₂ the two F atoms are axial and the three Cl atoms equatorial, so all moments cancel (μ = 0). PCl₂F₃, PCl₄F and PClF₄ cannot arrange their atoms so that every moment cancels (one equatorial position always differs from the other two).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-91","question":"Solid N₂O₅ is ionic, [NO₂]⁺[NO₃]⁻. The hybridisations of nitrogen in the cation and in the anion are respectively:","options":["sp² and sp²","sp and sp²","sp and sp³","sp² and sp"],"answer":1,"explanation":"NO₂⁺ is isoelectronic with CO₂: linear, sp nitrogen with two N=O bonds. NO₃⁻ is trigonal planar with sp² nitrogen and delocalised π bonding. In gaseous N₂O₅ both N are sp² (O₂N–O–NO₂), which is the trap.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-chemical-bonding-92", "question": "In the P₄O₁₀ molecule, the number of P–O–P bridges and the number of terminal P=O bonds are respectively:", "options": ["4 and 6", "6 and 6", "6 and 4", "4 and 4"], "answer": 2, "explanation": "P₄O₁₀ is the P₄O₆ cage (each of the 6 edges of the P₄ tetrahedron bridged by one O, so 6 P–O–P links) with one extra terminal oxygen on each of the 4 P atoms (4 P=O). Total P–O bonds = 12 + 4 = 16.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-chemical-bonding-93", "question": "Assertion (A): Removing an electron lengthens the bond in N₂ (N₂ → N₂⁺) but shortens it in O₂ (O₂ → O₂⁺). Reason (R): The highest occupied molecular orbital of N₂ is a bonding orbital, whereas that of O₂ is an antibonding π* orbital.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "N₂ loses an electron from the bonding σ2p orbital, so bond order falls 3 → 2.5 and the bond lengthens. O₂ loses an electron from π*, so bond order rises 2 → 2.5 and the bond shortens. R explains A.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-94","question":"Match the species (Column I) with its shape (Column II). (a) ClF₂⁺, (b) ClF₂⁻, (c) ClF₄⁺, (d) ClF₄⁻. (1) Linear, (2) Bent, (3) See-saw, (4) Square planar.","options":["a-1, b-2, c-3, d-4","a-2, b-1, c-4, d-3","a-3, b-1, c-2, d-4","a-2, b-1, c-3, d-4"],"answer":3,"explanation":"Count Cl electrons: ClF₂⁺ (6): 2 bp + 2 lp → bent. ClF₂⁻ (8): 2 bp + 3 lp → linear. ClF₄⁺ (6): 4 bp + 1 lp → see-saw. ClF₄⁻ (8): 4 bp + 2 lp → square planar. So a-2, b-1, c-3, d-4; the charge changes the lone-pair count, not just the formula.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-95","question":"How many of the following molecules have all their atoms in one plane: BF₃, C₂H₄, SF₄, XeF₄, H₂O₂, ClF₃, NO₂, S₈, B₂H₆?","options":["5","4","6","3"],"answer":0,"explanation":"Planar: BF₃ (trigonal), C₂H₄, XeF₄ (square planar), ClF₃ (T-shaped) and NO₂ (bent, three atoms) = 5. SF₄ is see-saw, H₂O₂ has an open-book (skew) shape, S₈ is a puckered crown and B₂H₆ has its bridging H atoms above and below the B₂H₄ plane.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-96","question":"The numbers of σ and π bonds in ethyne (HC≡CH) are respectively:","options":["2 and 3","3 and 2","5 and 0","3 and 1"],"answer":1,"explanation":"Each C–H is a σ bond (2), and the C≡C triple bond contains one σ and two π bonds. Total: 3 σ and 2 π.","difficulty":"easy","source":"NEET"},
  {"id":"chem-chemical-bonding-97","question":"Which of the following bonds has the greatest ionic character?","options":["Cs–F","Na–Cl","K–Br","Li–F"],"answer":0,"explanation":"Ionic character increases with electronegativity difference. Cs is the least electronegative of these metals and F the most electronegative element, so Cs–F has the largest difference (about 3.3).","difficulty":"easy","source":"NEET"},
  {"id":"chem-chemical-bonding-98","question":"The nitrite ion, NO₂⁻, has which of the following combinations of shape, nitrogen hybridisation and N–O bond order?","options":["Linear, sp, 2","Bent, sp³, 1","Trigonal planar, sp², 1.33","Bent, sp², 1.5"],"answer":3,"explanation":"N in NO₂⁻ has two σ bonds and one lone pair (three domains), so it is sp² and the ion is bent (about 115°). Two equivalent resonance structures share one π bond over two N–O links, giving bond order 1.5.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-99","question":"According to molecular orbital theory, the bond order of the peroxide ion, O₂²⁻, is:","options":["1.5","2","1","2.5"],"answer":2,"explanation":"O₂²⁻ has 18 electrons: bonding 10, antibonding 8 (π* fully filled). Bond order = (10 − 8)/2 = 1, consistent with the O–O single bond of peroxides; it is also diamagnetic.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-chemical-bonding-100","question":"The hybridisation of sulphur in the sulphate ion, SO₄²⁻, and the shape of the ion are:","options":["sp², trigonal planar","sp³, tetrahedral","sp³d², octahedral","dsp², square planar"],"answer":1,"explanation":"S forms four σ bonds to O and has no lone pair, so there are four electron domains: sp³ hybridisation and a regular tetrahedral ion. The extra π bonding (S=O character) does not change the σ framework.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-chemical-bonding-101","question":"Which of the following hydrides has the smallest H–E–H bond angle?","options":["H₂Te","H₂Se","H₂O","H₂S"],"answer":0,"explanation":"Down group 16 the central atom becomes larger and less electronegative; bonding pairs are held farther away and the bonds use nearly pure p orbitals. Angles fall: H₂O (104.5°) > H₂S (92°) > H₂Se (91°) > H₂Te (about 90°).","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-chemical-bonding-102","question":"Which of the following molecules has a non-zero dipole moment?","options":["XeF₄","PCl₅","CCl₄","SF₄"],"answer":3,"explanation":"SF₄ has a see-saw shape (four bond pairs + one lone pair), so its bond dipoles do not cancel. XeF₄ (square planar), PCl₅ (trigonal bipyramidal) and CCl₄ (tetrahedral) are symmetric and non-polar.","difficulty":"moderate","source":"NEET · JEE Main"},
  {"id":"chem-chemical-bonding-103","question":"Which of the following chlorides is the most covalent?","options":["MgCl₂","NaCl","SnCl₄","SnCl₂"],"answer":2,"explanation":"By Fajans' rules, a small, highly charged cation polarises the anion most. Sn⁴⁺ has a higher charge than Sn²⁺, Mg²⁺ or Na⁺, so SnCl₄ is the most covalent; it is in fact a fuming liquid, while SnCl₂ is a solid.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-104","question":"Using the expanded-octet Lewis structure, the average Cl–O bond order in the perchlorate ion, ClO₄⁻, is:","options":["2.00","1.75","1.50","1.33"],"answer":1,"explanation":"The best structure has three Cl=O and one Cl–O⁻; resonance spreads the 7 bonds over 4 equivalent Cl–O links, giving bond order 7/4 = 1.75. 1.50 would apply to sulphate (6/4) and 1.33 to carbonate or nitrate.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-105","question":"The hybridisations of the three carbon atoms in acrylonitrile, CH₂=CH–C≡N (from left to right), are:","options":["sp², sp², sp","sp², sp, sp","sp³, sp², sp","sp², sp², sp²"],"answer":0,"explanation":"The two alkene carbons each form three σ bonds and one π bond: sp². The nitrile carbon forms two σ bonds (to C and N) and two π bonds: sp.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-106","question":"The correct order of normal boiling points of H₂O, HF and NH₃ is:","options":["NH₃ > HF > H₂O","H₂O > NH₃ > HF","HF > H₂O > NH₃","H₂O > HF > NH₃"],"answer":3,"explanation":"Although the H–F hydrogen bond is the strongest individually, each H₂O can form two donor and two acceptor hydrogen bonds, giving an extended 3D network. Boiling points: H₂O 373 K > HF 293 K > NH₃ 240 K.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-107","question":"The H–P–H bond angle in PH₃ is about 93.5°, much smaller than the 107° in NH₃. The best explanation is:","options":["P–H bonds have more ionic character than N–H bonds","Phosphorus is more electronegative than nitrogen","Phosphorus uses almost pure p orbitals for bonding, with little s–p hybridisation","PH₃ has two lone pairs on phosphorus"],"answer":2,"explanation":"For larger, less electronegative central atoms (P, As, S, Se) the s–p energy gap is large, so the atom bonds mainly through its p orbitals (near 90°) and the lone pair stays in an s-rich orbital. Nitrogen hybridises effectively (sp³), giving 107°.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-108","question":"Which statement about the hydrogen peroxide molecule is correct?","options":["It is linear and non-polar","It has a non-planar 'open book' structure and a non-zero dipole moment","It is planar with both O–H bonds trans, so its dipole moment is zero","It contains an O=O double bond"],"answer":1,"explanation":"H₂O₂ is non-planar: the two O–H bonds lie in planes at a dihedral angle of about 111° (gas phase), so the bond dipoles do not cancel and μ ≈ 2.1 D. The O–O bond is a single bond.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-109","question":"Carbon suboxide, C₃O₂, is a linear molecule O=C=C=C=O. The numbers of σ and π bonds in it are:","options":["4 σ and 4 π","2 σ and 4 π","3 σ and 4 π","4 σ and 2 π"],"answer":0,"explanation":"There are four double bonds in the chain, each containing one σ and one π bond, so 4 σ and 4 π. All three carbons are sp hybridised, which makes the molecule linear.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-110","question":"When AlCl₃ dimerises to Al₂Cl₆ in the vapour phase, the hybridisation of aluminium changes from:","options":["sp³ to sp³d²","sp³ to sp²","sp² to sp³d","sp² to sp³"],"answer":3,"explanation":"Monomeric AlCl₃ is trigonal planar (sp², with an empty p orbital). In Al₂Cl₆ each Al accepts a lone pair from a bridging Cl, becoming four-coordinate and tetrahedral (sp³).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-111","question":"The correct order of bond dissociation enthalpies of the halogens is:","options":["F₂ > Cl₂ > Br₂ > I₂","Cl₂ > F₂ > Br₂ > I₂","Cl₂ > Br₂ > F₂ > I₂","I₂ > Br₂ > Cl₂ > F₂"],"answer":2,"explanation":"Bond enthalpies (kJ mol⁻¹) are Cl₂ 242 > Br₂ 193 > F₂ 158 > I₂ 151. F₂ is anomalously weak because its short bond brings the lone pairs on the two small F atoms close together, causing strong repulsion.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-112","question":"In the gas phase SnCl₂ exists as discrete molecules. Its shape and the hybridisation of tin are:","options":["Bent, sp³","Bent, sp²","Trigonal planar, sp²","Linear, sp"],"answer":1,"explanation":"Sn has 4 valence electrons; two form Sn–Cl bonds and two remain as a lone pair, so there are three electron domains (sp²). With one lone pair the molecule is bent (angle a little below 120°). Linear would require no lone pair, as in BeCl₂.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-113","question":"The geometries of the methyl cation (CH₃⁺), methyl anion (CH₃⁻) and methyl radical (CH₃•) are respectively:","options":["Trigonal planar, trigonal pyramidal, nearly planar","Tetrahedral, trigonal pyramidal, trigonal planar","Trigonal pyramidal, trigonal planar, tetrahedral","Trigonal planar, trigonal planar, trigonal pyramidal"],"answer":0,"explanation":"CH₃⁺ has three bond pairs and an empty p orbital: sp², planar. CH₃⁻ has three bond pairs and a lone pair: sp³, pyramidal like NH₃. CH₃• is essentially planar (sp²) with the odd electron in a p orbital.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-chemical-bonding-114","question":"According to MO theory (with s–p mixing), which of the following molecules is diamagnetic and has a bond order of 2 made up entirely of π bonding (no net σ bond)?","options":["O₂","B₂","N₂","C₂"],"answer":3,"explanation":"C₂ (12 electrons) is (σ1s)²(σ*1s)²(σ2s)²(σ*2s)²(π2p)⁴ with σ2p empty: the σ2s and σ*2s cancel, leaving two π bonds, bond order 2, all electrons paired. O₂ also has bond order 2 but is paramagnetic; B₂ is paramagnetic with bond order 1.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-115","question":"The shape of the XeOF₂ molecule and the hybridisation of xenon are:","options":["Trigonal planar, sp²","Trigonal pyramidal, sp³","T-shaped, sp³d","See-saw, sp³d"],"answer":2,"explanation":"Xe (8 valence electrons) forms one Xe=O and two Xe–F bonds, using 4 electrons and leaving 2 lone pairs. Five electron domains give sp³d; with the two lone pairs equatorial, the three atoms adopt a T-shape, like ClF₃.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-116","question":"How many of the following species have sp³d² hybridisation of the central atom? SF₆, XeF₄, BrF₅, [SiF₆]²⁻, PCl₅, IF₇, [ICl₄]⁻, XeF₂","options":["3","5","4","6"],"answer":1,"explanation":"Six electron domains (sp³d²): SF₆, XeF₄ (4 bp + 2 lp), BrF₅ (5 bp + 1 lp), [SiF₆]²⁻ and [ICl₄]⁻ (4 bp + 2 lp) — five species. PCl₅ and XeF₂ are sp³d, and IF₇ is sp³d³.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-117","question":"For which of the following pairs is the first ionisation energy of the diatomic molecule LOWER than that of the corresponding atom?","options":["O₂ and O","N₂ and N","H₂ and H","CO and C"],"answer":0,"explanation":"In O₂ the highest occupied MO is the antibonding π*2p, which lies above the atomic 2p level, so O₂ (12.1 eV) ionises more easily than O (13.6 eV). In N₂, H₂ and CO the electron is removed from a bonding orbital lying below the atomic level, so the molecule has the higher ionisation energy.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-118","question":"The shape of the BrF₄⁺ cation is:","options":["Tetrahedral","Square pyramidal","Square planar","See-saw"],"answer":3,"explanation":"Br has 7 − 1 = 6 valence electrons; 4 are used for Br–F bonds, leaving one lone pair. Five electron domains (sp³d) with one lone pair in an equatorial position give a see-saw shape, like SF₄. BrF₄⁻ (two lone pairs) is square planar.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-119","question":"In the trigonal bipyramidal PCl₅ molecule, the number of Cl–P–Cl bond angles that are exactly 90° is:","options":["3","4","6","12"],"answer":2,"explanation":"Each of the two axial Cl atoms makes a 90° angle with each of the three equatorial Cl atoms: 2 × 3 = 6. The three equatorial–equatorial angles are 120°, and the single axial–axial angle is 180°.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-120","question":"Tetracyanoethylene, (NC)₂C=C(CN)₂, contains:","options":["9 σ and 7 π bonds","9 σ and 9 π bonds","5 σ and 9 π bonds","13 σ and 9 π bonds"],"answer":1,"explanation":"C=C: 1 σ + 1 π; four C–C single bonds to the CN groups: 4 σ; four C≡N: 4 σ + 8 π. Total 9 σ and 9 π bonds.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-121","question":"Potassium hydrogen difluoride, KHF₂, is a stable salt, but the analogous KHCl₂ is not known under ordinary conditions. The reason is:","options":["F⁻ forms a very strong hydrogen bond with HF, giving the stable [F–H–F]⁻ ion, whereas the Cl–H···Cl⁻ interaction is weak","HF is a stronger acid than HCl","K⁺ is too small to stabilise the HCl₂⁻ ion","Chlorine cannot form any bond with hydrogen"],"answer":0,"explanation":"The [F–H–F]⁻ ion has an exceptionally strong, symmetric hydrogen bond (about 160 kJ mol⁻¹) because F is small and highly electronegative. Cl is larger and less electronegative, so the hydrogen bond in HCl₂⁻ is too weak. HF is actually a weaker acid than HCl.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-122","question":"How many of the following statements are correct? (A) All three C–O bonds in CO₃²⁻ are of equal length. (B) BF₃ has zero dipole moment. (C) In NH₄⁺ the N–H bond formed by coordination is longer than the other three. (D) For the same pair of atoms, a σ bond is generally stronger than a π bond. (E) An sp hybrid orbital has 50% s character.","options":["Only two","Only three","Only four","All five"],"answer":2,"explanation":"(A) true by resonance. (B) true: the trigonal planar bond dipoles cancel. (C) false: once formed, all four N–H bonds in NH₄⁺ are identical. (D) true: axial overlap is more effective. (E) true. Four are correct.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-chemical-bonding-123","question":"Which of the following species has the longest bond?","options":["N₂","N₂⁺","N₂⁻","N₂²⁻"],"answer":3,"explanation":"Bond orders: N₂ = 3, N₂⁺ = 2.5 (one bonding electron removed), N₂⁻ = 2.5 (one antibonding electron added), N₂²⁻ = 2 (two antibonding electrons). The lowest bond order gives the longest bond: N₂²⁻.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-124","question":"In a bent molecule AX₂, each A–X bond moment is 1.5 D and the measured dipole moment of the molecule is also 1.5 D. The X–A–X bond angle is:","options":["60°","120°","109.5°","90°"],"answer":1,"explanation":"Resultant μ = 2μ_b cos(θ/2). So 1.5 = 2 × 1.5 × cos(θ/2), cos(θ/2) = 0.5, θ/2 = 60° and θ = 120°. At 90° the resultant would be 2.12 D.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-chemical-bonding-125","question":"Which statement about diborane, B₂H₆, is correct?","options":["It has two 3-centre–2-electron B–H–B bonds and each boron is roughly sp³ hybridised","It is planar with four bridging hydrogens","It has an electron-precise B–B bond and each boron is sp²","All six B–H bonds are identical 2-centre–2-electron bonds"],"answer":0,"explanation":"B₂H₆ has four terminal 2c–2e B–H bonds and two bridging B–H–B 3c–2e ('banana') bonds above and below the plane of the B₂H₄ unit. Each B has four bonding directions and is roughly sp³. There is no B–B bond.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-chemical-bonding-126","question":"In an ionic crystal the cation-to-anion radius ratio is 0.52. According to the radius-ratio rule, the expected coordination number of the cation and its geometry are:","options":["4, tetrahedral","8, cubic","3, trigonal planar","6, octahedral"],"answer":3,"explanation":"Radius ratio 0.414–0.732 corresponds to octahedral coordination (CN 6), as in NaCl. 0.225–0.414 gives tetrahedral (CN 4) and above 0.732 gives cubic (CN 8).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-chemical-bonding-127","question":"The correct order of bond angles in Cl₂O, H₂O and OF₂ is:","options":["H₂O > Cl₂O > OF₂","H₂O > OF₂ > Cl₂O","Cl₂O > H₂O > OF₂","OF₂ > H₂O > Cl₂O"],"answer":2,"explanation":"In OF₂ the highly electronegative F pulls bonding pairs away from O, reducing bond-pair repulsion (103°). In Cl₂O the large Cl atoms crowd each other and the bonding pairs stay nearer O, so the angle opens to about 111°. H₂O lies between (104.5°).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-chemical-bonding-128","question":"Nitrogen exists as N≡N molecules, but phosphorus forms P₄ tetrahedra instead of P≡P molecules. The main reason is:","options":["Phosphorus is more electronegative than nitrogen","The larger 3p orbitals of phosphorus overlap poorly sideways, so pπ–pπ multiple bonds are weak","Phosphorus has no lone pair of electrons","P–P single bonds are much weaker than N–N single bonds"],"answer":1,"explanation":"Effective π bonding needs close approach and good sideways overlap of p orbitals. Phosphorus atoms are larger, so pπ–pπ overlap is poor and three P–P σ bonds per atom (P₄) are more stable than one σ + two π. For nitrogen the short N≡N bond is very strong (946 kJ mol⁻¹) while N–N single bonds are weak.","difficulty":"very-hard","source":"JEE Main"},
];

export default questions;
